package com.weearntogether.play

import android.content.Context
import android.graphics.*
import android.view.HapticFeedbackConstants
import android.view.MotionEvent
import android.view.View
import kotlin.math.*
import kotlin.random.Random

class BubbleShooterView(context: Context, private val onLevelComplete: (() -> Unit)? = null): View(context) {
    private val colors=intArrayOf(0xffff4f8b.toInt(),0xff36c9ff.toInt(),0xffffc83d.toInt(),0xff9b6cff.toInt())
    private val grid=Array(12){IntArray(8){-1}}; private val p=Paint(Paint.ANTI_ALIAS_FLAG)
    private val prefs=context.getSharedPreferences("bubble_shooter",Context.MODE_PRIVATE)
    private var current=0; private var next=0; private var shots=0; private var misses=0; private var points=0; private var level=1; private var streak=0
    private var best=prefs.getInt("best",0); private var bestLevel=prefs.getInt("best_level",1); private var ended=false; private var moving=false
    private var aimX=0f; private var aimY=0f; private var px=0f; private var py=0f; private var vx=0f; private var vy=0f; private var lastFrame=0L
    init { if(!restore()) newBoard() else sanitizeQueue() }
    private fun activeColors():List<Int>{val used=linkedSetOf<Int>();for(r in grid)for(v in r)if(v in colors.indices)used.add(v);return if(used.isEmpty())colors.indices.toList() else used.toList()}
    private fun playableColor()=activeColors().random()
    private fun sanitizeQueue(){val active=activeColors();if(current !in active)current=playableColor();if(next !in active)next=playableColor();save()}
    private fun missLimit()=(6-(level-1)/5).coerceAtLeast(3)
    private fun fillLevelBoard(){for(r in grid)r.fill(-1);val rows=(3+(level-1)/2).coerceAtMost(6);val colorCount=(3+(level-1)/3).coerceAtMost(colors.size);for(r in 0 until rows)for(c in 0..7)grid[r][c]=Random.nextInt(colorCount)}
    private fun newBoard(){level=1;fillLevelBoard();current=playableColor();next=playableColor();shots=0;misses=0;points=0;streak=0;ended=false;moving=false;aimX=0f;aimY=0f;save()}
    fun restart(){newBoard();invalidate()}
    fun swapBubble(){if(moving||ended)return;val t=current;current=next;next=t;save();performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);invalidate()}
    private fun restore():Boolean{val raw=prefs.getString("grid",null)?:return false;val cells=raw.split(",").mapNotNull{it.toIntOrNull()};if(cells.size!=96||cells.any{it !in -1 until colors.size})return false;for(i in cells.indices)grid[i/8][i%8]=cells[i];current=prefs.getInt("current",0).coerceIn(0,colors.lastIndex);next=prefs.getInt("nextPreview",0).coerceIn(0,colors.lastIndex);shots=prefs.getInt("shots",0).coerceAtLeast(0);misses=prefs.getInt("misses",0).coerceAtLeast(0);points=prefs.getInt("points",0).coerceAtLeast(0);level=prefs.getInt("level",1).coerceAtLeast(1);streak=prefs.getInt("streak",0).coerceAtLeast(0);ended=prefs.getBoolean("ended",false);return true}
    private fun save(){if(points>best)best=points;if(level>bestLevel)bestLevel=level;prefs.edit().putString("grid",grid.flatMap{it.asList()}.joinToString(",")).putInt("current",current).putInt("nextPreview",next).putInt("shots",shots).putInt("misses",misses).putInt("points",points).putInt("level",level).putInt("streak",streak).putInt("best",best).putInt("best_level",bestLevel).putBoolean("ended",ended).apply()}
    private fun radius()=width.toFloat()/17f; private fun centerX(c:Int,r:Int)=radius()*(1+2*c+(r%2)); private fun centerY(r:Int)=radius()*(2.35f+1.75f*r); private fun shooterY()=min(height.toFloat()-radius()*3.2f,radius()*28.7f)
    private fun neighbors(r:Int,c:Int):List<Pair<Int,Int>>{val d=if(r%2==0)arrayOf(-1 to -1,-1 to 0,0 to -1,0 to 1,1 to -1,1 to 0)else arrayOf(-1 to 0,-1 to 1,0 to -1,0 to 1,1 to 0,1 to 1);return d.map{(dr,dc)->r+dr to c+dc}.filter{(rr,cc)->rr in 0..11&&cc in 0..7}}
    private fun group(r:Int,c:Int,matching:Boolean):Set<Pair<Int,Int>>{val result=mutableSetOf(r to c);val q=ArrayDeque<Pair<Int,Int>>();q.add(r to c);while(q.isNotEmpty()){val(y,x)=q.removeFirst();for((yy,xx)in neighbors(y,x))if(grid[yy][xx]>=0&&(!matching||grid[yy][xx]==grid[r][c])&&result.add(yy to xx))q.add(yy to xx)};return result}
    private fun addPressureRow(){for(r in 11 downTo 1)for(c in 0..7)grid[r][c]=grid[r-1][c];val colorCount=(3+(level-1)/3).coerceAtMost(colors.size);for(c in 0..7)grid[0][c]=if(Random.nextFloat()<.82f)Random.nextInt(colorCount) else -1;misses=0;performHapticFeedback(HapticFeedbackConstants.LONG_PRESS)}
    private fun advanceLevel(){level++;bestLevel=maxOf(bestLevel,level);points+=250*level;streak++;misses=0;fillLevelBoard();current=playableColor();next=playableColor();shots=0;save();performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);post{onLevelComplete?.invoke()}}
    private fun finishGame(){if(ended)return;ended=true;save();performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);post{onLevelComplete?.invoke()}}
    private fun snap(){moving=false;val candidates=mutableListOf<Triple<Int,Int,Float>>();for(r in 0..11)for(c in 0..7)if(grid[r][c]<0){val connected=r==0||neighbors(r,c).any{(rr,cc)->grid[rr][cc]>=0};if(connected)candidates.add(Triple(r,c,hypot(px-centerX(c,r),py-centerY(r))))};val nearest=candidates.minByOrNull{it.third}?:run{finishGame();invalidate();return};val r=nearest.first;val c=nearest.second;grid[r][c]=current;val matches=group(r,c,true);if(matches.size>=3){streak++;misses=0;matches.forEach{(rr,cc)->grid[rr][cc]=-1};points+=matches.size*10*level+streak*5;val attached=mutableSetOf<Pair<Int,Int>>();for(col in 0..7)if(grid[0][col]>=0)attached.addAll(group(0,col,false));var dropped=0;for(rr in 0..11)for(cc in 0..7)if(grid[rr][cc]>=0&&(rr to cc)!in attached){grid[rr][cc]=-1;dropped++};points+=dropped*15*level;performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP)}else{streak=0;misses++;if(misses>=missLimit())addPressureRow()};shots++;if(grid.all{row->row.all{it<0}})advanceLevel()else{current=next;next=playableColor();if(current !in activeColors())current=playableColor()};if(grid[10].any{it>=0}||grid[11].any{it>=0})finishGame();save();invalidate()}
    private fun drawBubble(c:Canvas,x:Float,y:Float,rad:Float,color:Int){p.style=Paint.Style.FILL;p.shader=RadialGradient(x-rad*.30f,y-rad*.36f,rad*1.35f,intArrayOf(Color.WHITE,color,darken(color)),floatArrayOf(0f,.30f,1f),Shader.TileMode.CLAMP);c.drawCircle(x,y,rad,p);p.shader=null;p.color=0x66ffffff;p.style=Paint.Style.STROKE;p.strokeWidth=max(2f,rad*.07f);c.drawCircle(x,y,rad*.91f,p);p.style=Paint.Style.FILL;p.color=0xbfffffff.toInt();c.drawCircle(x-rad*.32f,y-rad*.34f,rad*.17f,p)}
    private fun darken(color:Int)=Color.rgb((Color.red(color)*.55f).toInt(),(Color.green(color)*.55f).toInt(),(Color.blue(color)*.55f).toInt())
    private fun pill(c:Canvas,left:Float,top:Float,right:Float,bottom:Float,color:Int){p.color=color;p.style=Paint.Style.FILL;c.drawRoundRect(left,top,right,bottom,(bottom-top)/2,(bottom-top)/2,p)}
    private fun label(c:Canvas,s:String,x:Float,y:Float,size:Float,color:Int=Color.WHITE){p.shader=null;p.style=Paint.Style.FILL;p.color=color;p.textSize=size;p.typeface=Typeface.create(Typeface.DEFAULT,Typeface.BOLD);c.drawText(s,x,y,p)}
    private fun drawAimGuide(c:Canvas){if(moving||ended||aimY<=0f)return;val rad=radius();val sx=width/2f;val sy=shooterY();val dx=aimX-sx;val dy=aimY-sy;if(dy>=-rad)return;val len=hypot(dx,dy).coerceAtLeast(1f);var ux=dx/len;val uy=dy/len;var x=sx;var y=sy;p.color=0xccecf7ff.toInt();repeat(36){x+=ux*rad*.62f;y+=uy*rad*.62f;if(x<rad||x>width-rad){ux=-ux;x=x.coerceIn(rad,width-rad())};if(y<=rad)return;p.alpha=(235-it*5).coerceAtLeast(55);c.drawCircle(x,y,rad*.095f,p);val collision=(0..11).any{r->(0..7).any{col->grid[r][col]>=0&&hypot(x-centerX(col,r),y-centerY(r))<rad*1.82f}};if(collision){p.alpha=255;p.style=Paint.Style.STROKE;p.strokeWidth=rad*.10f;p.color=0xaaffc84d.toInt();c.drawCircle(x,y,rad*.46f,p);p.style=Paint.Style.FILL;return}};p.alpha=255}
    override fun onDraw(c:Canvas){super.onDraw(c);val rad=radius();c.drawColor(0xff071020.toInt());p.shader=LinearGradient(0f,0f,width.toFloat(),height.toFloat(),intArrayOf(0xff101b43.toInt(),0xff27165b.toInt(),0xff071020.toInt()),null,Shader.TileMode.CLAMP);c.drawRect(0f,0f,width.toFloat(),height.toFloat(),p);p.shader=null;pill(c,rad*.35f,rad*.28f,width-rad*.35f,rad*1.82f,0xaa111a3a.toInt());label(c,"SCORE $points",rad*.62f,rad*1.05f,rad*.34f,gold());label(c,"BEST $best",rad*4.35f,rad*1.05f,rad*.34f);label(c,"LEVEL $level",rad*8.05f,rad*1.05f,rad*.34f,0xffcbb9ff.toInt());label(c,"COMBO x$streak",rad*11.7f,rad*1.05f,rad*.30f,0xff66e0b8.toInt());label(c,"DANGER $misses/${missLimit()}",rad*11.7f,rad*1.52f,rad*.27f,if(misses>=missLimit()-1)0xffff6b7a.toInt() else 0xffb9c7e8.toInt());for(r in 0..11)for(col in 0..7)if(grid[r][col]>=0)drawBubble(c,centerX(col,r),centerY(r),rad*.88f,colors[grid[r][col]]);drawAimGuide(c);p.color=0x552d7cff;c.drawCircle(width/2f,shooterY(),rad*1.38f,p);drawBubble(c,width/2f,shooterY(),rad*.92f,colors[current]);pill(c,rad*.45f,shooterY()-rad*.85f,rad*4.6f,shooterY()+rad*.95f,0xaa111a3a.toInt());label(c,"NEXT",rad*.8f,shooterY()-rad*.25f,rad*.40f,0xffb9c7e8.toInt());drawBubble(c,rad*3.65f,shooterY()+rad*.05f,rad*.52f,colors[next]);label(c,"TAP TO SWAP",rad*.72f,shooterY()+rad*.65f,rad*.31f,gold());if(moving){drawBubble(c,px,py,rad*.88f,colors[current]);val now=System.nanoTime();val dt=if(lastFrame==0L).016f else((now-lastFrame)/1e9f).coerceIn(.005f,.035f);lastFrame=now;px+=vx*dt;py+=vy*dt;if(px<rad||px>width-rad){vx=-vx;px=px.coerceIn(rad,width-rad)};if(py<=rad||(0..11).any{r->(0..7).any{col->grid[r][col]>=0&&hypot(px-centerX(col,r),py-centerY(r))<rad*1.8f}})snap()else postInvalidateOnAnimation()};if(ended){p.color=0xee080d22.toInt();c.drawRoundRect(rad,shooterY()/3,width-rad,shooterY()/3+rad*6.3f,rad*.65f,rad*.65f,p);label(c,"GAME OVER",rad*2.1f,shooterY()/3+rad*2f,rad*1.0f,gold());label(c,"Score $points • Level $level",rad*2.1f,shooterY()/3+rad*3.35f,rad*.58f);label(c,"Best level $bestLevel",rad*2.1f,shooterY()/3+rad*4.2f,rad*.48f,0xffcbb9ff.toInt());label(c,"Tap Restart to play again",rad*2.1f,shooterY()/3+rad*5.05f,rad*.43f,0xffb9c7e8.toInt())}}
    private fun gold()=0xffffc54d.toInt()
    override fun onTouchEvent(e:MotionEvent):Boolean{val rad=radius();when(e.action){MotionEvent.ACTION_DOWN->{if(!moving&&!ended&&hypot(e.x-rad*3.65f,e.y-(shooterY()+rad*.05f))<rad*1.3f){swapBubble();return true};if(!moving&&!ended){aimX=e.x;aimY=e.y;invalidate()};return true};MotionEvent.ACTION_MOVE->{if(!moving&&!ended){aimX=e.x;aimY=e.y;invalidate()};return true};MotionEvent.ACTION_UP->{if(moving||ended)return true;if(hypot(e.x-rad*3.65f,e.y-(shooterY()+rad*.05f))<rad*1.3f)return true;aimX=e.x;aimY=e.y;val dx=e.x-width/2f;val dy=e.y-shooterY();if(dy>=-rad)return true;val len=hypot(dx,dy).coerceAtLeast(1f);px=width/2f;py=shooterY();vx=dx/len*1350f;vy=dy/len*1350f;moving=true;lastFrame=0L;postInvalidateOnAnimation();return true}};return true}
}
